65	     1	/**
66	     2	 * @module scripts/bakeoff
67	     3	 *
68	     4	 * `npm run bakeoff -- <results.json> [more.json …]` — compares models from saved eval
69	     5	 * results (no API calls) and writes docs/bakeoff.md (B6).
70	     6	 *
71	     7	 * Several files for the same model are pooled (e.g. a screen run + a --repeat=2 run).
72	     8	 * Files graded by a judge other than JUDGE_MODEL (made with --rejudge and another
73	     9	 * JUDGE_MODEL) go into the cross-judge table (B3) instead of the ranking.
74	    10	 *
75	    11	 * Winner rule (B4): 1) gate: zero failures on premise/data checks and p95 ≤ 30 s;
76	    12	 * 2) accuracy: pass rate, where within 2 case-runs of the best counts as a tie;
77	    13	 * 3) cheapest per answer among the tied; 4) fastest as the final tiebreak.
78	    14	 */
79	    15	import { readFileSync, writeFileSync } from "node:fs";
80	    16	import { getJudgeEnv } from "../src/core/config/env";
81	    17	import { baseModel, judgeReliable, P95_LIMIT_SECONDS, rankModels, summarize, TIE_BAND_RUNS, type ResultsFile } from "../evals/lib/bakeoff";
82	    18	
83	    19	/** Formats a number to fixed decimals. */
84	    20	const f = (n: number, d = 1) => n.toFixed(d);
85	    21	
86	    22	/** Formats a USD amount per answer. */
87	    23	const usd = (n: number | null) => (n === null ? "n/a" : n < 0.01 ? `$${n.toFixed(4)}` : `$${n.toFixed(3)}`);
88	    24	
89	    25	/** Runs the comparison. */
90	    26	function main(): void {
91	    27	  const paths = process.argv.slice(2).filter((a) => !a.startsWith("--"));
92	    28	  if (paths.length === 0) throw new Error("Usage: npm run bakeoff -- <evals/results/…json> [more.json …]");
93	    29	  const primaryJudge = getJudgeEnv().JUDGE_MODEL;
94	    30	  const files = paths.map((p) => JSON.parse(readFileSync(p, "utf8")) as ResultsFile);
95	    31	  const modelOf = (f: ResultsFile) => baseModel(f.label);
96	    32	  const primary = files.filter((f) => f.judge === primaryJudge);
97	    33	  const cross = files.filter((f) => f.judge && f.judge !== primaryJudge);
98	    34	  /** Groups files by a key. */
99	    35	  const groupBy = (list: ResultsFile[], key: (f: ResultsFile) => string) => {
100	    36	    const map = new Map<string, ResultsFile[]>();
101	    37	    for (const file of list) map.set(key(file), [...(map.get(key(file)) ?? []), file]);
102	    38	    return map;
103	    39	  };
104	    40	
105	    41	  const byModel = new Map<string, ResultsFile[]>();
106	    42	  for (const file of primary) byModel.set(modelOf(file), [...(byModel.get(modelOf(file)) ?? []), file]);
107	    43	  const ranked = rankModels([...byModel].map(([model, fs]) => summarize(model, fs)));
108	    44	
109	    45	  const rows = ranked.map(
110	    46	    ({ summary: m, verdict }) =>
111	    47	      `| ${m.model} | ${m.passed}/${m.caseRuns} | ${m.gateFailures.length} | ${m.judgeFailures} | ${usd(m.costPerAnswer)} | ` +
112	    48	      `${f(m.avgSeconds)} / ${f(m.p95Seconds)} | ${f(m.avgToolCalls)} | ${m.duplicateCalls} | ${m.untraced} | ${m.retries} | ` +
113	    49	      `${m.faithful === null ? "n/a" : f(m.faithful)} | ${verdict} |`,
114	    50	  );
115	    51	  const failures = ranked
116	    52	    .filter(({ summary: m }) => m.failedCases.length)
117	    53	    .map(({ summary: m }) => `- **${m.model}**: ${m.failedCases.join(", ")}${m.gateFailures.length ? ` · gate: ${m.gateFailures.join("; ")}` : ""}`);
118	    54	  const crossRows = [...groupBy(cross, (file) => file.judge!)].flatMap(([judgeId, judgeFiles]) => {
119	    55	    const reliable = judgeReliable(judgeFiles);
120	    56	    return [...groupBy(judgeFiles, modelOf)].map(([model, modelFiles]) => {
121	    57	      const s = summarize(model, modelFiles);
122	    58	      const main = byModel.get(model) ? summarize(model, byModel.get(model)!) : null;
123	    59	      return (
124	    60	        `| ${judgeId} ${reliable ? "✅" : "❌ unreliable, ignore"} | ${model} | ${s.passed}/${s.caseRuns} | ${main ? `${main.passed}/${main.caseRuns}` : "n/a"} | ` +
125	    61	        `${s.judgeFailures} | ${main ? main.judgeFailures : "n/a"} | ${s.faithful === null ? "n/a" : f(s.faithful)} | ${s.judgeInconsistent} |`
126	    62	      );
127	    63	    });
128	    64	  });
129	    65	
130	    66	  const markdown = `# Model bakeoff
131	    67	
132	    68	Generated by \`npm run bakeoff\` from saved eval runs (same prompt, same 13 cases, no per-model tuning).
133	    69	Rule (D107): **gate** (zero premise/data check failures, p95 ≤ ${P95_LIMIT_SECONDS}s) → **accuracy** (within ${TIE_BAND_RUNS} case-runs of the best = tie) → **cost per answer** → **speed**.
134	    70	
135	    71	| Model | Cases passed | Gate fails | Judge fails | Cost / answer | Avg / p95 s | Tool calls | Dups | Untraced | Retries | Faithful (1–5) | Verdict |
136	    72	|---|---|---|---|---|---|---|---|---|---|---|---|
137	    73	${rows.join("\n")}
138	    74	
139	    75	${failures.length ? `## Failed cases\n${failures.join("\n")}\n` : ""}
140	    76	${
141	    77	  crossRows.length
142	    78	    ? `## Cross-judge check (B3)
143	    79	The same answers re-graded by a judge from another provider, to catch a judge favoring its own model family.
144	    80	A judge counts as reliable only if it grades all 3 planted answers right in every run and never contradicts itself (D109).
145	    81	
146	    82	| Cross judge | Model | Passed (cross) | Passed (${primaryJudge}) | Judge fails (cross) | Judge fails (${primaryJudge}) | Faithful (cross) | Self-contradicting |
147	    83	|---|---|---|---|---|---|---|---|
148	    84	${crossRows.join("\n")}
149	    85	`
150	    86	    : ""
151	    87	}`;
152	    88	  console.log(markdown);
153	    89	  if (process.argv.includes("--publish") || process.env.npm_config_publish === "true") {
154	    90	    writeFileSync("docs/bakeoff.md", markdown);
155	    91	    console.log("Written to docs/bakeoff.md");
156	    92	  }
157	    93	}
158	    94	
159	    95	try {
160	    96	  main();
161	    97	} catch (error) {
162	    98	  console.error(error instanceof Error ? error.message : error);
163	    99	  process.exit(1);
164	   100	}
