189	=== scripts/compute-fema-anchors.ts
190	     1	/**
191	     2	 * @module scripts/compute-fema-anchors
192	     3	 *
193	     4	 * Recomputes the FEMA "100" anchors (D47): the 95th percentile of each signal
194	     5	 * across all US counties where FEMA rates the hazard. Tornado is per area (D53);
195	     6	 * inland flood is per area with the area floored at the median US county (D123).
196	     7	 *
197	     8	 * `npm run fema:anchors` prints the values; they are then frozen by hand in
198	     9	 * src/core/scoring/config.ts (FEMA_ANCHORS_P95) so scores never shift silently
199	    10	 * when FEMA updates its data. Re-run when a new NRI version is released.
200	    11	 */
201	    12	import { fetchJsonWithRetry } from "../src/core/data/http";
202	    13	import { percentile, round } from "../src/core/utils/stats";
203	    14	
204	    15	const LAYER =
205	    16	  "https://services.arcgis.com/XG15cJAlne2vxtgt/arcgis/rest/services/National_Risk_Index_Counties/FeatureServer/0/query";
206	    17	const AFREQ_FIELDS = ["HRCN", "TRND", "HAIL", "IFLD", "CFLD", "ISTM", "WNTW", "CWAV", "HWAV", "SWND"] as const;
207	    18	
208	    19	type CountyRow = Record<string, number | string | null>;
209	    20	
210	    21	/**
211	    22	 * Downloads every county row (paged, 2,000 per page).
212	    23	 * @returns all county attribute rows.
213	    24	 */
214	    25	async function fetchAllCounties(): Promise<CountyRow[]> {
215	    26	  const rows: CountyRow[] = [];
216	    27	  for (let offset = 0; ; offset += 2_000) {
217	    28	    const params = new URLSearchParams({
218	    29	      where: "1=1",
219	    30	      outFields: ["STCOFIPS", "NRI_VER", "AREA", ...AFREQ_FIELDS.map((f) => `${f}_AFREQ`)].join(","),
220	    31	      returnGeometry: "false",
221	    32	      f: "json",
222	    33	      resultOffset: String(offset),
223	    34	      resultRecordCount: "2000",
224	    35	    });
225	    36	    const page = (await fetchJsonWithRetry({
226	    37	      url: `${LAYER}?${params.toString()}`,
227	    38	      boundary: "fema",
228	    39	      functionName: "fetchAllCounties",
229	    40	      errorName: "FemaFetchError",
230	    41	    })) as { features: { attributes: CountyRow }[]; exceededTransferLimit?: boolean };
231	    42	    rows.push(...page.features.map((feature) => feature.attributes));
232	    43	    if (!page.exceededTransferLimit) return rows;
233	    44	  }
234	    45	}
235	    46	
236	    47	/** Prints the p95 anchors. */
237	    48	async function main(): Promise<void> {
238	    49	  const rows = await fetchAllCounties();
239	    50	  console.log(`Counties: ${rows.length} · NRI version: ${rows[0]?.NRI_VER}`);
240	    51	  // Inland flood's area floor (D123): the median US county area → INLAND_FLOOD_AREA_FLOOR_SQ_MI.
241	    52	  const medianArea = percentile(rows.map((r) => Number(r.AREA)).filter((a) => a > 0), 0.5);
242	    53	  console.log(`${"Median county area".padEnd(34)} = ${round(medianArea, 1)} sq mi  (INLAND_FLOOD_AREA_FLOOR_SQ_MI)`);
243	    54	  for (const field of AFREQ_FIELDS) {
244	    55	    const rated = rows.filter((r) => r[`${field}_AFREQ`] !== null && Number(r.AREA) > 0);
245	    56	    const freq = (r: CountyRow) => Number(r[`${field}_AFREQ`]);
246	    57	    // Scored per 1,000 sq mi: tornado per county area (D53), inland flood per area floored at the median (D123).
247	    58	    const [label, values] =
248	    59	      field === "TRND"
249	    60	        ? ["TRND per 1,000 sq mi", rated.map((r) => (freq(r) / Number(r.AREA)) * 1_000)]
250	    61	        : field === "IFLD"
251	    62	          ? ["IFLD per 1,000 sq mi (area ≥ median)", rated.map((r) => (freq(r) / Math.max(Number(r.AREA), medianArea)) * 1_000)]
252	    63	          : [`${field}_AFREQ`, rated.map(freq)];
253	    64	    console.log(`${label.padEnd(34)} p95 = ${round(percentile(values, 0.95), 3)}  (n=${values.length})`);
254	    65	  }
255	    66	}
256	    67	
257	    68	main().catch((error: unknown) => {
258	    69	  console.error(error instanceof Error ? error.message : error);
259	    70	  process.exit(1);
260	    71	});
261	=== scripts/eval-guard.ts
262	     1	/**
263	     2	 * @module scripts/eval-guard
264	     3	 *
265	     4	 * `npm run eval:guard` — runs the guard eval set (evals/guardCases.ts) through the
266	     5	 * production guard (D118) and checks every case is allowed or declined as expected.
267	     6	 * Also reports the margins around the cutoffs, so tuning them is a measured choice.
268	     7	 *
269	     8	 *   npm run eval:guard                 one pass (~35 Jev calls, well under 1 cent)
270	     9	 *   npm run eval:guard -- --repeat=3   Jev isn't fully deterministic: check stability
271	    10	 *   npm run eval:guard -- --publish    also write docs/guard-evals.md
272	    11	 *
273	    12	 * Exit code 1 when any case gets the wrong decision (or Jev fails and the guard fails open).
274	    13	 */
275	    14	import { writeFileSync } from "node:fs";
276	    15	import { getJevEnv } from "../src/core/config/env";
277	    16	import { listActiveHubs } from "../src/core/db/hubsRepository";
278	    17	import { GUARD_CONFIG, runGuard, type GuardVerdict } from "../src/core/guard/jevGuard";
279	    18	import { GUARD_CASES, type GuardCase } from "../evals/guardCases";
280	    19	
281	    20	/** Reads `--name=value` (or PowerShell's `npm_config_name`). */
282	    21	function flag(name: string): string | undefined {
283	    22	  const arg = process.argv.find((a) => a.startsWith(`--${name}=`));
284	    23	  return arg ? arg.slice(name.length + 3) : process.env[`npm_config_${name}`];
285	    24	}
286	    25	
287	    26	/** Reads a boolean `--name` flag. */
288	    27	const has = (name: string) => process.argv.includes(`--${name}`) || process.env[`npm_config_${name}`] === "true";
289	    28	
290	    29	/** Formats a probability range over repeats. */
291	    30	const range = (xs: number[]) => (xs.length ? `${Math.min(...xs).toFixed(2)}–${Math.max(...xs).toFixed(2)}` : "n/a");
292	    31	
293	    32	/** Runs the guard eval. */
294	    33	async function main(): Promise<void> {
295	    34	  const repeat = Math.max(1, Number(flag("repeat") ?? 1));
296	    35	  const env = getJevEnv();
297	    36	  const hubNames = (await listActiveHubs()).map((hub) => `${hub.name}, ${hub.state}`);
298	    37	  console.log(`Guard eval: ${GUARD_CASES.length} cases × ${repeat} on ${env.JEV_MODEL} (decline if on-topic < ${GUARD_CONFIG.inScopeCutoff} or manipulation > ${GUARD_CONFIG.manipulationCutoff})…`);
299	    38	
300	    39	  const results: { c: GuardCase; verdicts: GuardVerdict[] }[] = [];
301	    40	  for (const c of GUARD_CASES) {
302	    41	    const verdicts: GuardVerdict[] = [];
303	    42	    for (let i = 0; i < repeat; i++) {
304	    43	      verdicts.push(await runGuard({ message: c.message, history: c.history, hubNames }, { apiKey: env.OPENROUTER_API_KEY, model: env.JEV_MODEL }));
305	    44	    }
306	    45	    results.push({ c, verdicts });
307	    46	  }
308	    47	
309	    48	  const rows = results.map(({ c, verdicts }) => {
310	    49	    const ok = verdicts.every((v) => !v.failedOpen && v.decision === c.expected);
311	    50	    const inScope = verdicts.flatMap((v) => (v.scores ? [v.scores.inScope] : []));
312	    51	    const manip = verdicts.flatMap((v) => (v.scores ? [v.scores.manipulation] : []));
313	    52	    return { c, ok, inScope, manip, got: [...new Set(verdicts.map((v) => (v.failedOpen ? "FAILED OPEN" : v.decision)))].join("/") };
314	    53	  });
315	    54	  for (const r of rows) {
316	    55	    console.log(
317	    56	      `${r.ok ? "✅" : "❌"} ${r.c.expected.padEnd(7)} ${(r.c.history.length ? "follow-up" : "first").padEnd(9)} ${r.c.kind.padEnd(12)} ${r.c.id.padEnd(16)} on-topic ${range(r.inScope)}  manipulation ${range(r.manip)}${r.ok ? "" : `  → got ${r.got}`}`,
318	    57	    );
319	    58	  }
320	    59	
321	    60	  const allow = rows.filter((r) => r.c.expected === "allow");
322	    61	  const passed = rows.filter((r) => r.ok).length;
323	    62	  const lowestAllowed = Math.min(...allow.flatMap((r) => r.inScope));
324	    63	  const highestAllowedManip = Math.max(...allow.flatMap((r) => r.manip));
325	    64	  const ms = results.flatMap((r) => r.verdicts.map((v) => v.ms)).sort((a, b) => a - b);
326	    65	  const p95 = ms[Math.floor(ms.length * 0.95)] ?? 0;
327	    66	  const summary = [
328	    67	    `${passed}/${rows.length} cases got the right decision${repeat > 1 ? ` in all ${repeat} runs` : ""}.`,
329	    68	    `Margins: lowest on-topic score of a message that must pass = ${lowestAllowed.toFixed(2)} (cutoff ${GUARD_CONFIG.inScopeCutoff}); highest manipulation score of a message that must pass = ${highestAllowedManip.toFixed(2)} (cutoff ${GUARD_CONFIG.manipulationCutoff}).`,
330	    69	    `Latency: median ${ms[Math.floor(ms.length / 2)]} ms, p95 ${p95} ms (timeout ${GUARD_CONFIG.timeoutMs} ms).`,
331	    70	  ];
332	    71	  console.log(`\n${passed === rows.length ? "🏆" : "⚠️ "} ${summary.join("\n   ")}`);
333	    72	
334	    73	  if (has("publish")) {
335	    74	    const table = rows
336	    75	      .map(
337	    76	        (r) =>
338	    77	          `| ${r.ok ? "✅" : "❌"} | \`${r.c.id}\` | ${r.c.message.replace(/\|/g, "\\|")} | ${r.c.history.length ? "follow-up" : "first"} | ${r.c.kind} | ${r.c.expected} | ${range(r.inScope)} | ${range(r.manip)} |`,
339	    78	      )
340	    79	      .join("\n");
341	    80	    writeFileSync(
342	    81	      "docs/guard-evals.md",
343	    82	      `# Guard eval results
344	    83	
345	    84	Latest run: **${env.JEV_MODEL}** · ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC · ${repeat} run(s) per case.
346	    85	Run it yourself: \`npm run eval:guard\`. The cases are in [evals/guardCases.ts](../evals/guardCases.ts), and how the guard works is in
347	    86	[design.md](design.md#9-errors-security-and-limits).
348	    87	
349	    88	The guard declines a message when Jev's probability that it's on topic is below **${GUARD_CONFIG.inScopeCutoff}**, or its probability that it
350	    89	tries to change the assistant's rules is above **${GUARD_CONFIG.manipulationCutoff}**. Follow-ups are judged together with the last
351	    90	${GUARD_CONFIG.historyTurns} turns.
