580	    47	    hubs: snapshots.map((s) => ({ id: s.hubId, name: ctx.hubById.get(s.hubId)!.name })),
581	    48	    ranking: (metric, region) => rankHubs(rows, { metric, region, order: "most", limit: 36 }).map((r) => r.hubId),
582	    49	    level: (hubId, hazard) => (hazard ? ctx.levelsByHub.get(hubId)!.hazards[hazard]! : ctx.levelsByHub.get(hubId)!.overall),
