621	    29	}
622	    30	
623	    31	/**
624	    32	 * Finds tool calls by name whose input matches a predicate.
625	    33	 * @param answer - the answer.
626	    34	 * @param tool - tool name.
627	    35	 * @param matches - predicate on the input (default: any).
628	    36	 * @returns the matching calls.
