630	    38	export function callsTo(answer: FinalAnswer, tool: string, matches: (input: Record<string, unknown>) => boolean = () => true): ToolCallRecord[] {
631	    39	  return answer.meta.toolCalls.filter((c) => c.tool === tool && matches((c.input ?? {}) as Record<string, unknown>));
632	    40	}
