634	    42	/**
635	    43	 * Which of the given hub names appears FIRST in the answer text.
636	    44	 * @param text - answer text.
637	    45	 * @param hubs - id + display name per hub.
638	    46	 * @returns the id of the earliest-mentioned hub, or null.
639	    47	 */
640	    48	export function firstHubMentioned(text: string, hubs: { id: string; name: string }[]): string | null {
641	    49	  let best: { id: string; at: number } | null = null;
642	    50	  for (const hub of hubs) {
643	    51	    const at = text.indexOf(hub.name);
644	    52	    if (at >= 0 && (!best || at < best.at)) best = { id: hub.id, at };
645	    53	  }
646	    54	  return best?.id ?? null;
647	    55	}
