649	    57	/**
650	    58	 * True when the text contains the number, allowing display rounding
651	    59	 * (9.04 may be written "9", "9.0" or "9.04").
652	    60	 * @param text - answer text.
653	    61	 * @param expected - the number to find.
654	    62	 * @returns whether it appears.
655	    63	 */
656	    64	export function textHasNumber(text: string, expected: number): boolean {
657	    65	  return collectNumbers(text).some((n) => Math.abs(n - expected) <= 0.051 || n === Math.round(expected));
658	    66	}
