661	    69	 * Counts duplicate tool calls (same tool + same input) — the "over-exploring" metric (E4).
662	    70	 * @param calls - the answer's tool calls.
663	    71	 * @returns how many calls repeated an earlier one.
664	    72	 */
665	    73	export function duplicateCalls(calls: ToolCallRecord[]): number {
666	    74	  const seen = new Set<string>();
667	    75	  let duplicates = 0;
668	    76	  for (const call of calls) {
669	    77	    const key = `${call.tool}:${JSON.stringify(call.input)}`;
670	    78	    if (seen.has(key)) duplicates++;
671	    79	    seen.add(key);
672	    80	  }
673	    81	  return duplicates;
674	    82	}
