490	    17	
491	    18	/** Check names that guard the "never wrong" promises: the premise verdict and the data (B4 gate). */
492	    19	export const GATE_CHECK = /premise|matches|computed|numbers|percentage/i;
493	    20	
494	    21	/** A saved eval results file (scripts/eval.ts output). */
495	    22	export interface ResultsFile {
