551	    78	export function summarize(model: string, files: ResultsFile[]): ModelSummary {
552	    79	  const runs = files.flatMap((f) => f.runs);
553	    80	  const metrics = softMetrics(runs, null);
554	    81	  // Cost per answer from the files that have a price (a re-judged file may not).
555	    82	  const priced = files.filter((f) => f.metrics.costUsd !== null);
556	    83	  const pricedTurns = priced.reduce((s, f) => s + f.metrics.turns, 0);
557	    84	  const costPerAnswer = pricedTurns ? priced.reduce((s, f) => s + f.metrics.costUsd!, 0) / pricedTurns : null;
