580	   107	/**
581	   108	 * Orders models by the B4 rule and says why each one lands where it does.
582	   109	 * @param models - model summaries.
583	   110	 * @returns ranked summaries with a short verdict each.
584	   111	 */
585	   112	export function rankModels(models: ModelSummary[]): { summary: ModelSummary; verdict: string }[] {
586	   113	  const rate = (m: ModelSummary) => m.passed / Math.max(1, m.caseRuns);
587	   114	  const gated = (m: ModelSummary) => m.gateFailures.length === 0 && m.p95Seconds <= P95_LIMIT_SECONDS;
588	   115	  const eligible = models.filter(gated);
589	   116	  const best = Math.max(0, ...eligible.map(rate));
590	   117	  const tied = (m: ModelSummary) => gated(m) && rate(m) >= best - TIE_BAND_RUNS / Math.max(1, m.caseRuns);
591	   118	  const order = (a: ModelSummary, b: ModelSummary) =>
592	   119	    Number(tied(b)) - Number(tied(a)) ||
593	   120	    Number(gated(b)) - Number(gated(a)) ||
594	   121	    (tied(a) && tied(b) ? (a.costPerAnswer ?? Infinity) - (b.costPerAnswer ?? Infinity) || a.avgSeconds - b.avgSeconds : rate(b) - rate(a));
595	   122	  return [...models].sort(order).map((summary, i) => ({
596	   123	    summary,
597	   124	    verdict: !gated(summary)
598	   125	      ? summary.gateFailures.length
599	   126	        ? "❌ fails the data/premise gate"
600	   127	        : `❌ p95 over ${P95_LIMIT_SECONDS}s`
601	   128	      : tied(summary)
602	   129	        ? i === 0
603	   130	          ? "🏆 top accuracy, cheapest"
604	   131	          : "tied on accuracy, costs more"
605	   132	        : "less accurate",
606	   133	  }));
607	   134	}
