    58	  const answers = turns.map((t) => t.answer).filter((a) => a !== null);
    59	  const seconds = turns.map((t) => t.ms / 1000).sort((a, b) => a - b);
    60	  const inputTokens = turns.reduce((s, t) => s + (t.usage?.inputTokens ?? 0), 0);
    61	  const outputTokens = turns.reduce((s, t) => s + (t.usage?.outputTokens ?? 0), 0);
    62	  const hasUsage = turns.some((t) => t.usage);
    63	  return {
    64	    turns: turns.length,
    65	    avgToolCalls: answers.length ? answers.reduce((s, a) => s + a.meta.toolCalls.length, 0) / answers.length : 0,
    66	    duplicateCalls: answers.reduce((s, a) => s + duplicateCalls(a.meta.toolCalls), 0),
    67	    untracedNumbers: answers.reduce((s, a) => s + a.meta.warnings.length, 0),
    68	    retries: answers.filter((a) => a.meta.retried).length,
    69	    avgSeconds: seconds.reduce((s, x) => s + x, 0) / Math.max(1, seconds.length),
    70	    p95Seconds: seconds[Math.min(seconds.length - 1, Math.floor(seconds.length * 0.95))] ?? 0,
    71	    inputTokens,
    72	    outputTokens,
    73	    costUsd: pricing && hasUsage ? inputTokens * pricing.input + outputTokens * pricing.output : null,
    74	  };
    75	}
