   148	    faithfulToData: avg((v) => v.faithfulToData)!,
   149	    answersQuestion: avg((v) => v.answersQuestion)!,
   150	    honestAboutLimits: avg((v) => v.honestAboutLimits)!,
   151	    premiseHandling: avg((v) => v.premiseHandling),
   152	    clarity: avg((v) => v.clarity)!,
